__d(function(a,e,i,n,r,u,l){r.exports={version:1,lang:"tr",sozler:[{id:"s-001",text:"S\xfcr\xfcden ayr\u0131lan\u0131 kurt kapar. Merak etme, bu masada tek kalan\u0131 en fazla g\xfclerek yerler.",oyun:"ok-mu-nok"},{id:"s-002",text:"Do\u011fru s\xf6yleyeni dokuz k\xf6yden kovarlar. Burada sadece tek ba\u015f\u0131na NOK'ta kal\u0131r.",oyun:"ok-mu-nok"},{id:"s-003",text:"Afrika yaban k\xf6pekleri ava \xe7\u0131k\u0131p \xe7\u0131kmamay\u0131 hap\u015f\u0131rarak oylar. Siz en az\u0131ndan ba\u015f parmak kullan\u0131yorsunuz.",oyun:"ok-mu-nok"},{id:"s-004",text:"\"OK\" ilk kez 1839'da bir Boston gazetesinde \"oll korrect\" \u015fakas\u0131yla bas\u0131ld\u0131. Yani OK bile yanl\u0131\u015f yaz\u0131lm\u0131\u015f bir do\u011fru.",oyun:"ok-mu-nok"},{id:"s-005",text:"Asch deneyinde kat\u0131l\u0131mc\u0131lar\u0131n yakla\u015f\u0131k %75'i en az bir kez bariz yanl\u0131\u015f cevapta gruba uydu. Ba\u015f parma\u011f\u0131n sana ait.",oyun:"ok-mu-nok"},{id:"s-006",text:"\"Ara vermi\u015ftik!\" Tek NOK'\xe7u olarak savunman\u0131 \u015fimdiden haz\u0131rla.",oyun:"ok-mu-nok"},{id:"s-007",text:"\"Joey yeme\u011fini payla\u015fmaz!\" \u0130lk bulu\u015fmada hesab\u0131 b\xf6lmeye NOK diyenlerin piri.",oyun:"ok-mu-nok"},{id:"s-008",text:"\"Ge\xe7emezsin!\" Gandalf da tek ba\u015f\u0131na NOK demi\u015fti, sonra efsane oldu.",oyun:"ok-mu-nok"},{id:"s-009",text:"\"Var m\u0131s\u0131n? Yok musun?\" Burada cevap tek bir ba\u015f parmak.",oyun:"ok-mu-nok"},{id:"s-010",text:"Herkes OK, sen NOK mu? Yanan odada kahvesini yudumlayan k\xf6pek gibi g\xfcl\xfcmse: \"This is fine.\"",oyun:"ok-mu-nok"},{id:"s-011",text:"1976'da Nadia Com\u0103neci ilk kusursuz 10'u ald\u0131, tabela 1.00 g\xf6sterdi. Tabela 10'a haz\u0131r de\u011fildi; sen haz\u0131r m\u0131s\u0131n?",oyun:"10-10-ama"},{id:"s-012",text:"Pratfall etkisi: \xc7ok ba\u015far\u0131l\u0131 biri kahvesini d\xf6k\xfcnce daha sevimli bulundu. K\xfc\xe7\xfck bir \"ama\" puan\u0131 y\xfckseltebilir.",oyun:"10-10-ama"},{id:"s-013",text:"Pisa Kulesi daha in\u015faat\u0131 bitmeden e\u011filmeye ba\u015flad\u0131. Y\xfczy\u0131llard\u0131r \"10/10 ama biraz yamuk\" diye geziliyor.",oyun:"10-10-ama"},{id:"s-014",text:"Japonlar k\u0131r\u0131k \xe7ana\u011f\u0131 alt\u0131nla onar\u0131r, ad\u0131 kintsugi. Bazen en parlak yer \"ama\"n\u0131n oldu\u011fu yerdir.",oyun:"10-10-ama"},{id:"s-015",text:"\"Kimse m\xfckemmel de\u011fildir.\" 10/10'un \"ama\"s\u0131 bile bir Hollywood klasi\u011fi.",oyun:"10-10-ama"},{id:"s-016",text:"\"Her a\xe7\u0131dan neredeyse kusursuz.\" \"Neredeyse\" kelimesi, \"ama\"n\u0131n kibar h\xe2lidir.",oyun:"10-10-ama"},{id:"s-017",text:"\"Bizimkiler on bire kadar \xe7\u0131k\u0131yor.\" \xdczg\xfcn\xfcz, bizim puan tablosu 10'da bitiyor.",oyun:"10-10-ama"},{id:"s-018",text:"Kusursuz dost arayan dostsuz kal\u0131r. Bir puan k\u0131r, arkada\u015fl\u0131\u011f\u0131 kurtar.",oyun:"10-10-ama"},{id:"s-019",text:"\"Devler so\u011fan gibidir, katman katman.\" Her \"ama\" da yeni bir katman.",oyun:"10-10-ama"},{id:"s-020",text:"\"Senden \xe7ok ho\u015flan\u0131yorum, tam oldu\u011fun gibi.\" \"Ama\"lar\u0131na ra\u011fmen 10 verenlere gelsin.",oyun:"10-10-ama"},{id:"s-021",text:"Koyunlar en az 50 koyun y\xfcz\xfcn\xfc iki y\u0131ldan uzun hat\u0131rlayabiliyor. S\xfcr\xfcye kar\u0131\u015fmak sand\u0131\u011f\u0131n kadar kolay de\u011fil, casus.",oyun:"casus-kim"},{id:"s-022",text:"\xc7atal kuyruklu drongo sahte alarm verir, mirketler ka\xe7\u0131nca yemeklerini kapar. Bu masada da yalanc\u0131 alarm bol.",oyun:"casus-kim"},{id:"s-023",text:"Ara\u015ft\u0131rmalara g\xf6re insanlar yalan\u0131 ancak %54 oran\u0131nda yakal\u0131yor; yaz\u0131 turadan biraz iyi. Oyunu ver ama emin olma.",oyun:"casus-kim"},{id:"s-024",text:"Taklit\xe7i ahtapot yass\u0131 bal\u0131k gibi davranarak tehlikeden s\u0131yr\u0131l\u0131r. Casus, sen de kelimeyi biliyormu\u015f gibi yap.",oyun:"casus-kim"},{id:"s-025",text:"\"Ad\u0131m Bond, James Bond.\" Ger\xe7ek casus ad\u0131n\u0131 iki kez s\xf6ylemez, kelimeyi hi\xe7 s\xf6ylemez.",oyun:"casus-kim"},{id:"s-026",text:"\"Hi\xe7bir \u015fey bilmiyorsun, Jon Snow.\" Casusun kelime hakk\u0131ndaki durumu tam olarak bu.",oyun:"casus-kim"},{id:"s-027",text:"Koyunlar \xf6mr\xfcn\xfc kurttan korkarak ge\xe7irir. Halbuki sonunda onu yiyen \xe7oband\u0131r.",oyun:"casus-kim"},{id:"s-028",text:"\"G\xfc\xe7 gizden gelir.\" Ezel biliyordu, casus da bilmeli: Fazla konu\u015fan yanar.",oyun:"casus-kim"},{id:"s-029",text:"Yalanc\u0131n\u0131n evi yanm\u0131\u015f, kimse inanmam\u0131\u015f. Bir tur yalan s\xf6yle, \xfc\xe7 tur \u015f\xfcpheli kal.",oyun:"casus-kim"},{id:"s-030",text:"Among Us'ta \u015f\xfcpheliye \"sus\" denir; T\xfcrk\xe7ede \"sus\" sessiz ol demek. Casus i\xe7in ikisi de ge\xe7erli.",oyun:"casus-kim"},{id:"s-031",text:"TDK'ya g\xf6re kafadar: G\xf6r\xfc\u015f ve anlay\u0131\u015flar\u0131 birbirine uyan kimselerden her biri. Yani sen ve yan\u0131ndakiler.",oyun:"genel"},{id:"s-032",text:"\u0130nsanlar ba\u015fkalar\u0131yla birlikteyken, yaln\u0131zken oldu\u011fundan 30 kat daha s\u0131k g\xfcl\xfcyor. Bu oyun tek ba\u015f\u0131na oynanmaz.",oyun:"genel"},{id:"s-033",text:"Bir ara\u015ft\u0131rmaya g\xf6re yak\u0131n arkada\u015f olmak i\xe7in 200 saatten fazla birlikte vakit gerekiyor. Bu tur da say\u0131l\u0131r.",oyun:"genel"},{id:"s-034",text:"Kea papa\u011fan\u0131n\u0131n \"oyun \xe7a\u011fr\u0131s\u0131\" bula\u015f\u0131c\u0131d\u0131r; duyan ku\u015flar da oynamaya ba\u015flar. Hadi, siz de bula\u015f\u0131n.",oyun:"genel"},{id:"s-035",text:"Ur Kraliyet Oyunu yakla\u015f\u0131k 4.500 y\u0131ll\u0131k; kurallar\u0131 bir \xe7ivi yaz\u0131s\u0131 tabletten \xe7\xf6z\xfcld\xfc. Bizimkiler daha k\u0131sa.",oyun:"genel"},{id:"s-036",text:"\"Hayat bir kutu \xe7ikolata gibidir; ne \xe7\u0131kaca\u011f\u0131 belli olmaz.\" Kartlar da \xf6yle.",oyun:"genel"},{id:"s-037",text:"\"San\u0131r\u0131m bu, g\xfczel bir dostlu\u011fun ba\u015flang\u0131c\u0131.\" Oyun bitince de ge\xe7erli.",oyun:"genel"},{id:"s-038",text:"\"Kurallar daha \xe7ok y\xf6nerge gibidir.\" Korsanlarda \xf6yle; Kafadar'da kural kurald\u0131r.",oyun:"genel"},{id:"s-039",text:"\"Sevgi neydi? Sevgi iyilikti, dostluktu, sevgi emekti.\" Oyundan sonra masay\u0131 toplamak da emek.",oyun:"genel"},{id:"s-040",text:"Bir elin nesi var, iki elin sesi var. Alt\u0131 elin ise kahkahas\u0131.",oyun:"genel"},{id:"s-041",text:"Bilmedi\u011fin soruya 'ben zaten bunu biliyordum' demek de bir beceridir. Burada puan getirmez ama.",oyun:"quiz-night"},{id:"s-042",text:"D\xf6rt \u015f\u0131k var, do\u011fru bir tane. Gerisi, 'ama ben \u015fuydu sanm\u0131\u015ft\u0131m' diyenlere.",oyun:"quiz-night"},{id:"s-043",text:"Bu quizde yanl\u0131\u015f cevap puan d\xfc\u015f\xfcrmez; sadece masadaki k\u0131skan\xe7l\u0131k seviyesini y\xfckseltir.",oyun:"quiz-night"},{id:"s-044",text:"Unvan puana g\xf6re verilir, kibir kimseye bedava. Yine de iyi ta\u015f\u0131.",oyun:"quiz-night"},{id:"s-045",text:"Son soruya geldin. Ya efsane olursun ya \xe7ok iyi bir an\u0131 b\u0131rak\u0131rs\u0131n.",oyun:"quiz-night"},{id:"s-046",text:"Telefonu tutan okur, herkes ba\u011f\u0131r\u0131r, bilen sessizce g\xfcl\xfcmser. Klasik.",oyun:"quiz-night"},{id:"s-047",text:"'Bunu bilmem zaten' diyenler listesi bu turun sonunda a\xe7\u0131klan\u0131r.",oyun:"quiz-night"},{id:"s-048",text:"\u015e\u0131klardan ikisini hemen eleyebiliyorsan yar\u0131 yoldas\u0131n. Kalan\u0131 cesaret.",oyun:"quiz-night"},{id:"s-049",text:"Bir dizi se\xe7, bir fan ol. Fanl\u0131\u011f\u0131n puan\u0131 ise 10 \xfczerinden hesaplan\u0131r.",oyun:"quiz-night"},{id:"s-050",text:"\u0130lk kolay sorulara dikkat: en \xe7ok gurur orada k\u0131r\u0131l\u0131r.",oyun:"quiz-night"}]}},814,[]);
